import{Q as e,Z as t,ft as n,t as r}from"./chunks/framework.3dCkIOgK.js";var i=JSON.parse(`{"title":"Migrate Your Cloud Storage","description":"","frontmatter":{},"headers":[],"relativePath":"usage/remote-migration.md","filePath":"en/usage/remote-migration.md","lastUpdated":1790560748000}`),a={name:`usage/remote-migration.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="migrate-your-cloud-storage" tabindex="-1">Migrate Your Cloud Storage <a class="header-anchor" href="#migrate-your-cloud-storage" aria-label="Permalink to “Migrate Your Cloud Storage”">​</a></h1><p>Some features, like <a href="./../deep-dive/asymmetric-storage">Asymmetric Storage</a> and <a href="./../deep-dive/modules/encryption">Encryption</a>, require your remote storage be in a different format. When you toggle those features but the remote is still in an incompatible format, Sync Engine could produce catastrophic sync results.</p><p>Sync Engine itself does not try to migrate the remote format automatically. This is because sync strategies may differ across devices, and a Sync Engine installation on one device cannot reliably perform a migration without leaving the remote or other devices in a broken partial state. This might be improved in the future, but a manual migration is currently necessary when you toggle those features.</p><p>This page elaborates how to safely perform a manual migration with Sync Engine.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li>Perform synchronizations on all your devices to ensure that they all have the latest set of files.</li><li>Choose one of your devices that has the most files and best network as your primary operating device, exit Obsidian on other devices.</li><li>Temporarily turn off realtime and scheduled syncing on that device to prevent accidental interference.</li><li>Adjust <a href="./settings#sync-strategy">sync strategies</a> temporarily and perform syncs to ensure that the vault on this device has the <strong>complete set of files</strong> you need to upload to remote. When done, finally adjust sync strategies to ensure that <strong>&quot;Mirror local&quot; strategy is applied to this whole set of files</strong>.</li><li><strong>Find <a href="./settings#clear-records">Clear records</a> in development settings and click &quot;Clear&quot;</strong>.</li><li>Copy the entire set of files to a different place as backup.</li><li>Go to the file management interface of your cloud storage, <strong>manually delete all previously synchronized files, or remove the base directory directly</strong>.</li><li>Toggle the feature that changes the remote format (like encryption or asymmetric storage), a migration pop-up reminder should be shown, click &quot;Confirm&quot;.</li><li>Now trigger a manual sync, a preview full of upload operations should be shown. Review the files to upload and start syncing, wait for the mass upload to complete.</li><li><strong>Turn off all network connections on other devices and enter Obsidian on each device</strong>, toggle the same feature that you want to migrate for.</li><li>Restore network connections on these devices, and start a manual trial sync each. The sync should complete as already synchronized with no additional operations to perform.</li><li>Restore sync strategies and realtime / scheduled sync settings on your primary device. Then the migration is complete.</li></ol>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};